  function detect(navLangs) {
    for (const l of navLangs || []) {
      const b = String(l).toLowerCase().split(/[-_]/)[0];
      if (b === 'nb' || b === 'nn' || b === 'no') return 'nb';
      if (D[b]) return b;
    }
    return 'en';
  }
  function create(lang) {
    lang = D[lang] ? lang : 'nb';
    const dict = D[lang], loc = LOCALE[lang];
    const t = (k, v) => { if (v && +v.n === 1 && (k + '.1') in dict) k += '.1'; let s = dict[k] ?? D.en[k] ?? D.nb[k] ?? k; if (v) for (const x in v) s = s.split('{' + x + '}').join(v[x]); return s; };
    const nf = (n, d = 0) => new Intl.NumberFormat(loc, { maximumFractionDigits: d }).format(+n || 0);
    const kgf = n => +n > 0 ? t('kg', { n: nf(n, 1) }) : t('bw');
    const date = (d, o) => new Intl.DateTimeFormat(loc, o).format(new Date(d));
    const hm = d => date(d, { hour: '2-digit', minute: '2-digit' });
    const weekdays = () => [...Array(7)].map((_, i) => date(new Date(2024, 0, 1 + i), { weekday: 'short' }).replace('.', ''));
    return { lang, locale: loc, t, nf, kgf, date, hm, weekdays, exName: id => t('n.' + id) };
  }
